def forward(self, taskInfo):
    """Ask the LLM to produce a step‑by‑step reasoning and a computable expression, then evaluate
    the expression. Run two CoT agents with slightly different temperatures and vote on the
    final numeric answer. The function returns an `Info` object with the best answer.
    """
    # Instruction for the LLM: produce reasoning and a Python expression for the answer
    cot_instruction = (
        "Please think step by step and then solve the task. "
        "After your reasoning, provide the final answer as a valid Python expression "
        "using only integers, +, -, *, //, (, and ). Do NOT include any other text."
    )

    # Create two CoT agents with different temperatures to generate diverse expressions
    cot_agent_low = LLMAgentBase(["thinking", "answer_expr"], "CoT Expression Agent Low", temperature=0.2)
    cot_agent_high = LLMAgentBase(["thinking", "answer_expr"], "CoT Expression Agent High", temperature=0.8)

    # Helper: safely evaluate a simple arithmetic expression
    def safe_eval(expr: str):
        import ast
        import operator as op

        operators = {ast.Add: op.add, ast.Sub: op.sub, ast.Mult: op.mul, ast.FloorDiv: op.floordiv}

        def _eval(node):
            if isinstance(node, ast.Expression):
                return _eval(node.body)
            elif isinstance(node, ast.BinOp):
                left = _eval(node.left)
                right = _eval(node.right)
                oper = operators[type(node.op)]
                return oper(left, right)
            elif isinstance(node, (ast.Num, ast.Constant)):
                val = node.n if hasattr(node, "n") else node.value
                if not isinstance(val, (int, float)):
                    raise ValueError("Unsupported constant type")
                return val
            elif isinstance(node, ast.UnaryOp) and isinstance(node.op, ast.USub):
                return -_eval(node.operand)
            else:
                raise ValueError(f"Unsupported expression: {type(node)}")

        parsed = ast.parse(expr, mode="eval")
        return _eval(parsed)

    # Run both agents and collect expressions
    exprs = []
    for agent in (cot_agent_low, cot_agent_high):
        try:
            _, expr_info = agent([taskInfo], cot_instruction)
            expr = expr_info.content.strip()
            exprs.append(expr)
        except Exception:
            continue

    # Evaluate each expression and collect results
    results = []
    for expr in exprs:
        try:
            val = safe_eval(expr)
            # Convert float results that are whole numbers to int
            if isinstance(val, float) and abs(val - int(val)) < 1e-9:
                val = int(val)
            results.append(str(val))
        except Exception:
            continue

    # Vote on the most common result (simple majority). If no valid result, fall back to the first expression string.
    if results:
        from collections import Counter
        most_common = Counter(results).most_common(1)[0][0]
        final_answer = most_common
    else:
        # All evaluations failed – return the raw expression of the first agent
        final_answer = exprs[0] if exprs else ""

    # Return the answer as an Info object
    return Info("answer", "Expression CoT with Majority Voting", final_answer, -1)
